//! The built-in name lists of ADR-0049 decision 8, one set per PostgreSQL
//! major version (14 to 18), generated by `builtins/generate.sh` from a
//! fresh server of the engine-matrix image of that major (the image
//! digest is in each file's header) and embedded here: function names
//! (`pg_proc` of `pg_catalog`, and of `information_schema` qualified),
//! operator symbols (`pg_operator` of `pg_catalog`), type names (`pg_type`
//! of `pg_catalog`, and of `information_schema` qualified) and keywords
//! with their category (`pg_get_keywords()`). Each list is exact for every
//! minor version of its major (ADR-0049 re-review N5; the drift test of
//! `it.rs` compares them with the server's catalogs both ways).
//!
//! A server older than the oldest list has no list: the caller treats
//! every unqualified name as not built in. A server newer than the newest
//! list uses the newest one, with a warning logged once: names added since
//! are not on it, so they are reported (fail closed).

use std::sync::OnceLock;
use std::sync::atomic::{AtomicBool, Ordering};

/// Oldest and newest major versions with lists.
pub(crate) const OLDEST_MAJOR: u32 = 14;
pub(crate) const NEWEST_MAJOR: u32 = 18;

/// The category of a keyword (`pg_get_keywords().catcode`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum KeywordCategory {
    /// `U`: unreserved, a plain identifier everywhere.
    Unreserved,
    /// `C`: a column name, never a bare function or type name; the
    /// grammar's own forms (`COALESCE (`, `VALUES (`, `numeric (`,
    /// `SUBSTRING (`).
    ColumnName,
    /// `T`: a type or function name, also infix syntax (`LIKE`, `JOIN`).
    TypeFunctionName,
    /// `R`: reserved.
    Reserved,
}

/// The lists of one major version.
pub(crate) struct Builtins {
    /// The major version the lists were generated for.
    pub(crate) major: u32,
    functions: Vec<&'static str>,
    information_schema_functions: Vec<&'static str>,
    operators: Vec<&'static str>,
    types: Vec<&'static str>,
    information_schema_types: Vec<&'static str>,
    keywords: Vec<(&'static str, KeywordCategory)>,
}

impl std::fmt::Debug for Builtins {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Builtins")
            .field("major", &self.major)
            .finish_non_exhaustive()
    }
}

/// The raw files of one major version.
struct Raw {
    major: u32,
    functions: &'static str,
    operators: &'static str,
    types: &'static str,
    keywords: &'static str,
}

macro_rules! raw {
    ($major:literal) => {
        Raw {
            major: $major,
            functions: include_str!(concat!("../../builtins/", $major, "/functions.txt")),
            operators: include_str!(concat!("../../builtins/", $major, "/operators.txt")),
            types: include_str!(concat!("../../builtins/", $major, "/types.txt")),
            keywords: include_str!(concat!("../../builtins/", $major, "/keywords.txt")),
        }
    };
}

const RAW: [Raw; 5] = [raw!(14), raw!(15), raw!(16), raw!(17), raw!(18)];

/// The lines of a list file, header comments (`# …`, a hash and a space:
/// no name starts so, while operators such as `#`, `##` and `#>` do) left
/// out.
fn lines(raw: &'static str) -> impl Iterator<Item = &'static str> {
    raw.lines()
        .filter(|l| !l.is_empty() && !l.starts_with("# "))
}

const INFORMATION_SCHEMA: &str = "information_schema.";

/// Names of `pg_catalog` and of `information_schema`, each sorted.
fn split_schemas(raw: &'static str) -> (Vec<&'static str>, Vec<&'static str>) {
    let mut catalog = Vec::new();
    let mut information = Vec::new();
    for l in lines(raw) {
        match l.strip_prefix(INFORMATION_SCHEMA) {
            Some(n) => information.push(n),
            None => catalog.push(l),
        }
    }
    catalog.sort_unstable();
    information.sort_unstable();
    (catalog, information)
}

impl Builtins {
    fn parse(raw: &Raw) -> Self {
        let (functions, information_schema_functions) = split_schemas(raw.functions);
        let (types, information_schema_types) = split_schemas(raw.types);
        let mut operators: Vec<&'static str> = lines(raw.operators).collect();
        operators.sort_unstable();
        let mut keywords: Vec<(&'static str, KeywordCategory)> = lines(raw.keywords)
            .filter_map(|l| {
                let (w, c) = l.split_once(' ')?;
                let c = match c {
                    "U" => KeywordCategory::Unreserved,
                    "C" => KeywordCategory::ColumnName,
                    "T" => KeywordCategory::TypeFunctionName,
                    "R" => KeywordCategory::Reserved,
                    _ => return None,
                };
                Some((w, c))
            })
            .collect();
        keywords.sort_unstable_by_key(|(w, _)| *w);
        Self {
            major: raw.major,
            functions,
            information_schema_functions,
            operators,
            types,
            information_schema_types,
            keywords,
        }
    }

    /// A function name of `pg_catalog`.
    pub(crate) fn function(&self, name: &str) -> bool {
        self.functions.binary_search(&name).is_ok()
    }

    /// A function name of `information_schema`.
    pub(crate) fn information_schema_function(&self, name: &str) -> bool {
        self.information_schema_functions
            .binary_search(&name)
            .is_ok()
    }

    /// An operator symbol of `pg_catalog`.
    pub(crate) fn operator(&self, symbol: &str) -> bool {
        self.operators.binary_search(&symbol).is_ok()
    }

    /// A type name of `pg_catalog`.
    pub(crate) fn type_name(&self, name: &str) -> bool {
        self.types.binary_search(&name).is_ok()
    }

    /// A type name of `information_schema`.
    pub(crate) fn information_schema_type(&self, name: &str) -> bool {
        self.information_schema_types.binary_search(&name).is_ok()
    }

    /// The category of a keyword (an unquoted word).
    pub(crate) fn keyword(&self, word: &str) -> Option<KeywordCategory> {
        self.keywords
            .binary_search_by_key(&word, |(w, _)| *w)
            .ok()
            .map(|i| self.keywords[i].1)
    }

    /// The `pg_catalog` types an unquoted SQL type spelling always means,
    /// whatever the search path (the grammar's `SystemTypeName`): `None`
    /// for a name the grammar resolves like any other (`text`, `int4`,
    /// `date`). `double precision` comes merged by the scan.
    pub(crate) fn keyword_type(&self, name: &str) -> Option<&'static [&'static str]> {
        let targets: &'static [&'static str] = match name {
            "int" | "integer" => &["int4"],
            "smallint" => &["int2"],
            "bigint" => &["int8"],
            "real" => &["float4"],
            "float" => &["float4", "float8"],
            "double precision" => &["float8"],
            "decimal" | "dec" | "numeric" => &["numeric"],
            "boolean" => &["bool"],
            "bit" => &["bit", "varbit"],
            "character" | "char" | "national" | "nchar" => &["bpchar", "varchar"],
            "varchar" => &["varchar"],
            "timestamp" => &["timestamp", "timestamptz"],
            "time" => &["time", "timetz"],
            "interval" => &["interval"],
            // A keyword from PostgreSQL 16 on.
            "json" if self.keyword("json").is_some() => &["json"],
            _ => return None,
        };
        Some(targets)
    }
}

static LISTS: [OnceLock<Builtins>; 5] = [
    OnceLock::new(),
    OnceLock::new(),
    OnceLock::new(),
    OnceLock::new(),
    OnceLock::new(),
];

/// Set once a server newer than the newest list was seen.
static NEWER_WARNED: AtomicBool = AtomicBool::new(false);

/// The lists for a server (`server_version_num`): `None` below
/// [`OLDEST_MAJOR`]; the newest lists above [`NEWEST_MAJOR`], with a
/// warning logged once.
pub(crate) fn for_server(server_version_num: u32) -> Option<&'static Builtins> {
    let major = server_version_num / 10_000;
    if major < OLDEST_MAJOR {
        return None;
    }
    if major > NEWEST_MAJOR && !NEWER_WARNED.swap(true, Ordering::Relaxed) {
        tracing::warn!(
            major,
            lists = NEWEST_MAJOR,
            "PostgreSQL server newer than the agent's built-in name lists: the newest lists are \
             used, and functions, operators and types added since are reported as user code \
             next to catalogs (ADR-0049 decision 8)"
        );
    }
    let k = usize::try_from(major.min(NEWEST_MAJOR) - OLDEST_MAJOR).ok()?;
    let raw = RAW.get(k)?;
    Some(LISTS.get(k)?.get_or_init(|| Builtins::parse(raw)))
}

/// The lines of one list file of `major` (`functions`, `operators`,
/// `types`, `keywords`), header left out (the drift test).
#[cfg(test)]
pub(crate) fn raw_lines(major: u32, kind: &str) -> Vec<&'static str> {
    let Some(raw) = RAW.iter().find(|r| r.major == major) else {
        return Vec::new();
    };
    let file = match kind {
        "functions" => raw.functions,
        "operators" => raw.operators,
        "types" => raw.types,
        _ => raw.keywords,
    };
    lines(file).collect()
}

/// Whether `f` holds for the lists of every major version (a database
/// whose version is not known yet: only what holds on every version).
pub(crate) fn all_majors(f: &dyn Fn(&Builtins) -> bool) -> bool {
    (OLDEST_MAJOR..=NEWEST_MAJOR).all(|m| for_server(m * 10_000).is_some_and(f))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_major_has_sorted_lists_with_a_header() {
        for raw in &RAW {
            for (file, kind) in [
                (raw.functions, "functions"),
                (raw.operators, "operators"),
                (raw.types, "types"),
                (raw.keywords, "keywords"),
            ] {
                let header = file.lines().next().unwrap_or_default();
                assert!(
                    header.starts_with(&format!("# PostgreSQL {}.", raw.major)),
                    "{} {kind}: {header}",
                    raw.major
                );
                assert!(
                    header.contains("@sha256:") || header.contains("local cluster"),
                    "{} {kind}: source not recorded",
                    raw.major
                );
                // Sorted by byte value, no duplicate (the generator's
                // `COLLATE "C"`).
                let l: Vec<&str> = lines(file).collect();
                assert!(l.len() > 50, "{} {kind}", raw.major);
                assert!(
                    l.windows(2).all(|w| w[0] < w[1]),
                    "{} {kind}: not sorted",
                    raw.major
                );
            }
        }
    }

    #[test]
    fn lookups_per_major() {
        let b16 = for_server(160_013).unwrap();
        assert_eq!(b16.major, 16);
        assert!(b16.function("length"));
        assert!(b16.function("pg_get_userbyid"));
        assert!(!b16.function("my_f"));
        assert!(b16.information_schema_function("_pg_expandarray"));
        assert!(!b16.function("_pg_expandarray"));
        assert!(b16.operator("="));
        assert!(b16.operator("~~*"));
        assert!(b16.operator("#>>"));
        assert!(b16.operator("#"));
        assert!(!b16.operator("+++"));
        assert!(b16.type_name("int4"));
        assert!(b16.type_name("text"));
        assert!(!b16.type_name("integer"));
        assert!(b16.information_schema_type("sql_identifier"));
        assert_eq!(b16.keyword("select"), Some(KeywordCategory::Reserved));
        assert_eq!(b16.keyword("coalesce"), Some(KeywordCategory::ColumnName));
        assert_eq!(b16.keyword("left"), Some(KeywordCategory::TypeFunctionName));
        assert_eq!(b16.keyword("by"), Some(KeywordCategory::Unreserved));
        assert_eq!(b16.keyword("length"), None);
        assert_eq!(b16.keyword_type("integer"), Some(&["int4"][..]));
        assert_eq!(b16.keyword_type("json"), Some(&["json"][..]));
        assert_eq!(b16.keyword_type("text"), None);
        // Per major: JSON is a keyword from 16, `pg_read_file_old` is gone
        // in 17, `system_user` is reserved from 16.
        let b14 = for_server(140_024).unwrap();
        assert_eq!(b14.keyword_type("json"), None);
        assert!(b14.function("pg_read_file_old"));
        assert!(!for_server(170_011).unwrap().function("pg_read_file_old"));
        assert_eq!(b14.keyword("system_user"), None);
        assert_eq!(b16.keyword("system_user"), Some(KeywordCategory::Reserved));
        // 17 adds MERGE_ACTION as a keyword.
        assert_eq!(
            for_server(170_011).unwrap().keyword("merge_action"),
            Some(KeywordCategory::ColumnName)
        );
        // Older than the oldest: none; newer than the newest: the newest.
        assert!(for_server(130_020).is_none());
        assert_eq!(for_server(190_000).unwrap().major, NEWEST_MAJOR);
    }
}
